"use client";

import { useState } from "react";
import { AgencySectionHeading } from "@/components/jabkit/agency-section-heading";
import { cn } from "@/lib/cn";
import { agencyServiceItems } from "./AgencyServicesSection.mocks";
import type { AgencyServicesSectionProps } from "./AgencyServicesSection.types";

const defaults = {
  id: "services",
  number: "04",
  label: "Services",
  meta: "04 categories",
  title: "What I do",
} as const;

export function AgencyServicesSection({
  className,
  id = defaults.id,
  number = defaults.number,
  label = defaults.label,
  meta = defaults.meta,
  title = defaults.title,
  items = [...agencyServiceItems],
  ...props
}: AgencyServicesSectionProps) {
  const [openIndex, setOpenIndex] = useState(0);

  return (
    <section
      id={id}
      data-slot="agency-services-section"
      className={cn("bg-background text-foreground", className)}
      {...props}
    >
      <div className="mx-auto max-w-[90rem] px-[var(--jk-space-gutter)] py-16">
        <AgencySectionHeading
          number={number}
          label={label}
          meta={meta}
          title={title}
        />
        <ul className="mt-10 border-t border-foreground">
          {items.map((item, index) => {
            const open = openIndex === index;
            return (
              <li key={item.number} className="border-b border-foreground">
                <button
                  type="button"
                  className={cn(
                    "flex w-full items-center justify-between gap-4 rounded-none px-0 py-5 text-left transition-colors duration-300 motion-reduce:transition-none",
                    open
                      ? "bg-foreground px-4 text-background sm:px-5"
                      : "bg-background text-foreground hover:bg-muted",
                  )}
                  aria-expanded={open}
                  onClick={() => setOpenIndex(open ? -1 : index)}
                >
                  <span className="font-[family-name:var(--jk-font-display)] text-xl font-semibold uppercase tracking-tight sm:text-3xl">
                    {item.number} {item.title}
                  </span>
                  <span aria-hidden="true" className="font-mono text-lg">
                    {open ? "−" : "+"}
                  </span>
                </button>
                <div
                  className={cn(
                    "grid transition-[grid-template-rows] duration-300 ease-out motion-reduce:transition-none",
                    open ? "grid-rows-[1fr]" : "grid-rows-[0fr]",
                  )}
                >
                  <div className="overflow-hidden">
                    <p
                      className={cn(
                        "max-w-[62ch] px-4 py-5 text-sm leading-relaxed sm:px-5",
                        open
                          ? "bg-foreground text-background"
                          : "bg-background text-muted-foreground",
                      )}
                    >
                      {item.body}
                    </p>
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      </div>
    </section>
  );
}

import type { HTMLAttributes } from "react";

export interface AgencyServiceItem {
  number: string;
  title: string;
  body: string;
}

export interface AgencyServicesSectionProps
  extends HTMLAttributes<HTMLElement> {
  id?: string;
  number?: string;
  label?: string;
  meta?: string;
  title?: string;
  items?: AgencyServiceItem[];
}

import type { AgencyServicesSectionProps } from "./AgencyServicesSection.types";

export const agencyServiceItems = [
  {
    number: "01",
    title: "Identity",
    body: "Naming, marks, type systems, and the rules that keep a brand readable across print and screen.",
  },
  {
    number: "02",
    title: "Editorial",
    body: "Publications, campaigns, and long-form layouts where hierarchy and paper still matter.",
  },
  {
    number: "03",
    title: "Web",
    body: "Sites and interfaces built as typographic systems, not template skins.",
  },
  {
    number: "04",
    title: "Direction",
    body: "Art direction and commissioning across photography, motion, and production partners.",
  },
] as const;

export const agencyServicesSectionMocks = {
  default: {
    id: "services",
    number: "04",
    label: "Services",
    meta: "04 categories",
    title: "What I do",
    items: [...agencyServiceItems],
  },
  alternate: {
    id: "services",
    number: "03",
    label: "Practice",
    meta: "03 categories",
    title: "How we work",
    items: [
      {
        number: "01",
        title: "Audit",
        body: "A short read of the current system before any new marks are drawn.",
      },
      {
        number: "02",
        title: "Build",
        body: "A focused set of assets and rules, not a 200-page unused brand book.",
      },
      {
        number: "03",
        title: "Steer",
        body: "Ongoing direction when the first applications hit print and product.",
      },
    ],
  },
} satisfies Record<string, AgencyServicesSectionProps>;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...classes: ClassValue[]) {
  return twMerge(clsx(classes));
}
